use serde_json::json;use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/loose-complex-square176";
fn main(){let rustc="/home/ubuntu/.rustup/toolchains/1.98.1-x86_64-unknown-linux-gnu/bin/rustc";let parent="/home/ubuntu/src/zopro-perf-work/crt-euler176/target/release/deps";let helper="/home/ubuntu/src/zopro-perf-work/tool-target/release/deps";let mut pins=BTreeMap::new();let mut pin=|p:String|{let bytes=fs::read(&p).unwrap();pins.insert(p,format!("{:x}",Sha256::digest(bytes)));};for d in[parent,helper]{for e in fs::read_dir(d).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_file()&&matches!(p.extension().and_then(|x|x.to_str()),Some("rlib"|"rmeta"|"so")){pin(p.display().to_string());}}}for p in[format!("{R}/design.md"),format!("{R}/model.rs"),format!("{R}/prepare.rs"),format!("{R}/model-initial.rs"),format!("{R}/pre-build-repairs.md"),rustc.into()]{pin(p);}let output=format!("{R}/model-pins.json");assert!(!Path::new(&output).exists());fs::write(&output,serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let command=|name:&str,argv:Vec<String>|json!({"kind":"command","name":name,"argv":argv,"timeout_seconds":600,"environment":{},"unfiltered":false});let args=vec![rustc.into(),"--edition=2021".into(),"-O".into(),format!("{R}/model.rs"),"-L".into(),format!("dependency={parent}"),"-L".into(),format!("dependency={helper}"),"--extern".into(),format!("num_bigint={parent}/libnum_bigint-be646e83c0c62d72.rlib"),"--extern".into(),format!("num_traits={parent}/libnum_traits-c2e07c77c90d1316.rlib"),"--extern".into(),format!("serde_json={helper}/libserde_json-cdebb9338c2784ad.rlib"),"-o".into(),format!("{R}/model")];let plan=json!({"version":1,"source_pins":output,"steps":[command("compile-model",args),command("exact-integer-model",vec![format!("{R}/model")])]});fs::write(format!("{R}/model-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Prepared signed integer model, {} pins, two commands",pins.len());}
